package com.personal.assistant.module.automation.service;import com.personal.assistant.common.exception.*;import com.personal.assistant.module.inbox.dto.InboxCreateRequest;import com.personal.assistant.module.inbox.service.InboxService;import com.personal.assistant.module.reminder.dto.ReminderRequest;import com.personal.assistant.module.reminder.service.ReminderService;import com.personal.assistant.module.report.service.ReportService;import com.personal.assistant.module.task.dto.*;import com.personal.assistant.module.task.service.TaskService;import org.springframework.stereotype.Service;import java.time.*;import java.util.Map;
@Service public class AutomationActionService{private final TaskService tasks;private final ReminderService reminders;private final InboxService inbox;private final ReportService reports;public AutomationActionService(TaskService tasks,ReminderService reminders,InboxService inbox,ReportService reports){this.tasks=tasks;this.reminders=reminders;this.inbox=inbox;this.reports=reports;}public Long act(Long uid,String ruleName,String actionType,Map<String,Object>cfg,String sourceTitle,LocalDateTime now){String title=String.valueOf(cfg.getOrDefault("title",sourceTitle));return switch(actionType){case "CREATE_REMINDER","SEND_NOTIFICATION"->reminders.create(uid,new ReminderRequest("CUSTOM",null,longValue(cfg.get("channelId")),title,String.valueOf(cfg.getOrDefault("content",sourceTitle)),now.plusMinutes(number(cfg.get("delayMinutes"),5))));case "CREATE_TASK"->tasks.create(uid,new TaskUpsertRequest(title,TaskType.valueOf(String.valueOf(cfg.getOrDefault("taskType","LIFE"))),TaskPriority.valueOf(String.valueOf(cfg.getOrDefault("priority","MEDIUM"))),TaskStatus.NOT_STARTED,now,null,false,null,null,"由自动化规则「"+ruleName+"」创建",String.valueOf(cfg.getOrDefault("category","自动化")),String.valueOf(cfg.getOrDefault("workType","自动化")),null));case "ADD_INBOX"->inbox.create(uid,new InboxCreateRequest(String.valueOf(cfg.getOrDefault("content",title)))).getId();case "GENERATE_REPORT"->reports.generate(uid,String.valueOf(cfg.getOrDefault("reportType","WEEKLY")),now.toLocalDate()).getId();default->throw new BusinessException(ErrorCode.VALIDATION_ERROR,"动作不支持");};}private int number(Object v,int d){try{return v==null?d:Integer.parseInt(String.valueOf(v));}catch(Exception e){return d;}}private Long longValue(Object v){return v==null?null:Long.valueOf(String.valueOf(v));}}
